local CoinPressMaker = {}
local PRODUCTS = {
    iron_coin_press = { name = "Železno stiskalo za kovance", ironCost = 5, woodCost = 1, leatherCost = 1, time = 6, cost = 205, prestige = 5, happiness = 2, description = "Železno stiskalo za kovanje kovancev." },
    bronze_coin_press = { name = "Bronasto stiskalo za kovance", bronzeCost = 5, ironCost = 1, woodCost = 1, leatherCost = 1, time = 8, cost = 495, prestige = 7, happiness = 3, description = "Bronasto stiskalo za precizno kovanje." },
    silver_coin_press = { name = "Srebrno stiskalo za kovance", silverCost = 5, bronzeCost = 1, ironCost = 1, woodCost = 1, leatherCost = 1, time = 12, cost = 1190, prestige = 12, happiness = 4, description = "Srebrno stiskalo za plemiške kovance." },
    gilded_coin_press = { name = "Pozlačeno stiskalo za kovance", goldCost = 1, silverCost = 5, bronzeCost = 1, woodCost = 1, leatherCost = 1, time = 16, cost = 2550, prestige = 21, happiness = 5, description = "Pozlačeno stiskalo za dvorne kovance." },
    jewel_set_coin_press = { name = "Draguljasto stiskalo za kovance", goldCost = 2, silverCost = 5, jewelCost = 1, bronzeCost = 1, woodCost = 1, leatherCost = 1, time = 20, cost = 5500, prestige = 37, happiness = 7, description = "Draguljasto stiskalo za kraljevske kovance." },
    royal_sovereign_coin_press = { name = "Kraljevski suvereno stiskalo za kovance", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 27, cost = 11700, prestige = 70, happiness = 13, description = "Suvereno stiskalo z biseri za krono." },
}
local BUILDINGS = {
    coinpress_workshop = { name = "Kovaška delavnica", cost = { gold = 390, wood = 175, stone = 160, iron = 11 }, upkeep = 8, qualityBonus = 5 },
    coinpress_house = { name = "Kovaška hiša", cost = { gold = 1340, wood = 360, stone = 300, silver = 8, iron = 9 }, upkeep = 29, qualityBonus = 18 },
    master_coinpress_atelier = { name = "Mojstrski kovaški atelje", cost = { gold = 3300, wood = 425, stone = 560, silver = 40, gold = 8 }, upkeep = 77, qualityBonus = 30 },
    sovereign_coinpress_palace = { name = "Suverena kovaška palača", cost = { gold = 14000, wood = 660, stone = 880, gold = 90, jewel = 20 }, upkeep = 267, qualityBonus = 55, prestigeBonus = 50 },
}
CoinPressMaker.ironStock = 18; CoinPressMaker.bronzeStock = 14; CoinPressMaker.woodStock = 10; CoinPressMaker.leatherStock = 8; CoinPressMaker.silverStock = 8; CoinPressMaker.goldStock = 6; CoinPressMaker.jewelStock = 4; CoinPressMaker.pearlStock = 4
CoinPressMaker.productStock = {}; CoinPressMaker.buildings = {}; CoinPressMaker.maker = nil; CoinPressMaker.activeMaking = {}; CoinPressMaker.totalProducts = 0; CoinPressMaker.dayTimer = 0
function CoinPressMaker.init() CoinPressMaker.ironStock=18; CoinPressMaker.bronzeStock=14; CoinPressMaker.woodStock=10; CoinPressMaker.leatherStock=8; CoinPressMaker.silverStock=8; CoinPressMaker.goldStock=6; CoinPressMaker.jewelStock=4; CoinPressMaker.pearlStock=4; CoinPressMaker.productStock={}; CoinPressMaker.buildings={}; CoinPressMaker.maker=nil; CoinPressMaker.activeMaking={}; CoinPressMaker.totalProducts=0; CoinPressMaker.dayTimer=0; print("[CoinPressMaker] Royal Coin Press Maker System initialized (6 products, 4 buildings)") end
function CoinPressMaker.hireMaker(n,s) s=s or math.random(55,90); local c=595+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; CoinPressMaker.maker={name=n or ("Kovalec "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kovalec najet: %s (spretnost: %d)",CoinPressMaker.maker.name,s),"success") end; return true end
function CoinPressMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function CoinPressMaker.build(id) local ok,e=CoinPressMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(CoinPressMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function CoinPressMaker.getQualityBonus() local b=0; for _,bd in ipairs(CoinPressMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function CoinPressMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and CoinPressMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and CoinPressMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and CoinPressMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and CoinPressMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and CoinPressMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and CoinPressMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and CoinPressMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and CoinPressMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #CoinPressMaker.buildings==0 then return false,"Potrebna kovaška delavnica" end; if not CoinPressMaker.maker then return false,"Potreben kovalec" end; return true end
function CoinPressMaker.make(pt,qty) qty=qty or 1; local ok,e=CoinPressMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then CoinPressMaker.ironStock=CoinPressMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then CoinPressMaker.bronzeStock=CoinPressMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then CoinPressMaker.woodStock=CoinPressMaker.woodStock-d.woodCost*qty end; if d.leatherCost then CoinPressMaker.leatherStock=CoinPressMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then CoinPressMaker.silverStock=CoinPressMaker.silverStock-d.silverCost*qty end; if d.goldCost then CoinPressMaker.goldStock=CoinPressMaker.goldStock-d.goldCost*qty end; if d.jewelCost then CoinPressMaker.jewelStock=CoinPressMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then CoinPressMaker.pearlStock=CoinPressMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if CoinPressMaker.maker then t=math.max(1,t-math.floor(CoinPressMaker.maker.skill/13)) end; table.insert(CoinPressMaker.activeMaking,{id="coinpress_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function CoinPressMaker.completeMaking(m) local q=1.0+(CoinPressMaker.getQualityBonus()/100); if CoinPressMaker.maker then q=q+(CoinPressMaker.maker.skill/140) end; q=math.min(2.5,q); CoinPressMaker.productStock[m.productType]=(CoinPressMaker.productStock[m.productType] or 0)+m.quantity; CoinPressMaker.totalProducts=CoinPressMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if CoinPressMaker.maker then CoinPressMaker.maker.itemsMade=CoinPressMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then CoinPressMaker.maker.skill=math.min(100,CoinPressMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Stiskalo izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"coinpress.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function CoinPressMaker.update(dt) if not _G.state then return end; CoinPressMaker.dayTimer=CoinPressMaker.dayTimer+dt; if CoinPressMaker.dayTimer>=30 then CoinPressMaker.dayTimer=0; for i=#CoinPressMaker.activeMaking,1,-1 do local m=CoinPressMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then CoinPressMaker.completeMaking(m); table.remove(CoinPressMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(CoinPressMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if CoinPressMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function CoinPressMaker.getStats() return {ironStock=CoinPressMaker.ironStock,bronzeStock=CoinPressMaker.bronzeStock,woodStock=CoinPressMaker.woodStock,leatherStock=CoinPressMaker.leatherStock,silverStock=CoinPressMaker.silverStock,goldStock=CoinPressMaker.goldStock,jewelStock=CoinPressMaker.jewelStock,pearlStock=CoinPressMaker.pearlStock,productStock=CoinPressMaker.productStock,numBuildings=#CoinPressMaker.buildings,hasMaker=CoinPressMaker.maker~=nil,makerName=CoinPressMaker.maker and CoinPressMaker.maker.name or "—",makerSkill=CoinPressMaker.maker and CoinPressMaker.maker.skill or 0,activeMaking=#CoinPressMaker.activeMaking,totalProducts=CoinPressMaker.totalProducts} end
return CoinPressMaker
